// LeadFlow Free - step 1: your leads (synthetic sample rows).
// Quick start: press "Execute workflow" and open the Result node.
// For your own data, replace the rows below, or swap this node for
// "Read/Write Files from Disk" + "Extract from File" (CSV) to load a .csv file.
const leads = [
  { first_name: 'Ana', last_name: 'Kovač', email: 'ana.kovac@example.com', company: 'Prima Studio' },
  { first_name: 'Marko', last_name: 'Petrović', email: 'marko.petrovic@example.com', company: 'Petro Co' },
  { first_name: 'Ana', last_name: 'Kovač', email: 'ana.kovac@example.com', company: 'Prima Studio' },
  { first_name: 'Jürgen', last_name: 'Müller', email: 'juergen.mueller@example.com', company: 'Muller GmbH' },
  { first_name: 'Sara', last_name: 'Alić', email: 'sara.alic@example.com', company: 'Alfa' },
  { first_name: 'Marko', last_name: 'Petrović', email: 'MARKO.PETROVIC@example.com', company: 'Petro Co' }
];
return leads.map((lead) => ({ json: lead }));

// LeadFlow Free - step 2: keep one row per email (case-insensitive).
// The first row wins; a row without an email is kept as-is.
const rows = $input.all().map((item) => item.json);
const seen = new Map();
const withoutEmail = [];
for (const row of rows) {
  const key = String(row.email || '').trim().toLowerCase();
  if (!key) { withoutEmail.push(row); continue; }
  if (!seen.has(key)) seen.set(key, { ...row, email: key });
}
const unique = [...seen.values(), ...withoutEmail];
return unique.map((row) => ({ json: row }));

// LeadFlow Free - step 3: honest summary of what this run did.
const rows = $input.all().map((item) => item.json);
return [{ json: {
  unique_leads_out: rows.length,
  note: 'One row per email, lowercased. No credentials were used in this run.',
  unique_leads: rows,
} }];
